{
  "actions": [
    {
      "title": "Find Stores",
      "description": "Retrieves a paginated list of store objects ordered by name. Use this endpoint to fetch store information which may be used in subsequent filtering of resources.",
      "type": "action",
      "documentation": "https://docs.lemonsqueezy.com/api/stores",
      "endpointUrl": "/stores",
      "apiBaseUrl": "https://api.lemonsqueezy.com/v1/",
      "method": "GET",
      "sampleResponse": {
        "data": [
          {
            "id": "1",
            "attributes": {
              "name": "My Store",
              "domain": "mystore.example.com"
            }
          }
        ]
      },
      "inputSchema": {
        "type": "object",
        "description": "No additional input parameters are required for this endpoint.",
        "properties": {}
      },
      "outputType": {
        "outputType": "array",
        "arrayPropertyValue": "data"
      }
    },
    {
      "title": "Find Products",
      "description": "Retrieves a paginated list of product objects ordered by name. You can filter products by providing a store_id.",
      "type": "action",
      "documentation": "https://docs.lemonsqueezy.com/api/products",
      "endpointUrl": "/products",
      "apiBaseUrl": "https://api.lemonsqueezy.com/v1/",
      "method": "GET",
      "sampleResponse": {
        "data": [
          {
            "id": "101",
            "attributes": {
              "name": "Digital Course",
              "price": "29.99"
            }
          }
        ]
      },
      "inputSchema": {
        "type": "object",
        "description": "Input parameter to filter products.",
        "properties": {
          "store_id": {
            "type": "string",
            "description": "ID of the store to filter products."
          }
        }
      },
      "outputType": {
        "outputType": "array",
        "arrayPropertyValue": "data"
      }
    },
    {
      "title": "Find Customers",
      "description": "Retrieves a paginated list of customer objects. Use the query parameter to search for customers based on name or email.",
      "type": "action",
      "documentation": "https://docs.lemonsqueezy.com/api/customers",
      "endpointUrl": "/customers",
      "apiBaseUrl": "https://api.lemonsqueezy.com/v1/",
      "method": "GET",
      "sampleResponse": {
        "data": [
          {
            "id": "501",
            "attributes": {
              "email": "customer@example.com",
              "name": "John Doe"
            }
          }
        ]
      },
      "inputSchema": {
        "type": "object",
        "description": "Optional search parameter to filter customers.",
        "properties": {
          "query": {
            "type": "string",
            "description": "Search term to filter customers by name or email."
          }
        }
      },
      "outputType": {
        "outputType": "array",
        "arrayPropertyValue": "data"
      }
    },
    {
      "title": "Find Orders",
      "description": "Retrieves a paginated list of order objects. Filter orders by store ID, customer ID, or customer email.",
      "type": "action",
      "documentation": "https://docs.lemonsqueezy.com/api/orders",
      "endpointUrl": "/orders",
      "apiBaseUrl": "https://api.lemonsqueezy.com/v1/",
      "method": "GET",
      "sampleResponse": {
        "data": [
          {
            "id": "9001",
            "attributes": {
              "status": "completed",
              "total": "49.99"
            }
          }
        ]
      },
      "inputSchema": {
        "type": "object",
        "description": "Optional filters to narrow down order results.",
        "properties": {
          "store_id": {
            "type": "string",
            "description": "ID of the store to filter orders."
          },
          "customer_id": {
            "type": "string",
            "description": "ID of the customer associated with the order."
          },
          "user_email": {
            "type": "string",
            "description": "Email of the customer for order filtering."
          }
        }
      },
      "outputType": {
        "outputType": "array",
        "arrayPropertyValue": "data"
      }
    },
    {
      "title": "Find Subscriptions",
      "description": "Retrieves a paginated list of subscription objects. Use various filter parameters to refine subscription search, such as store ID, customer ID, order ID, product ID, variant ID, or subscription status.",
      "type": "action",
      "documentation": "https://docs.lemonsqueezy.com/api/subscriptions",
      "endpointUrl": "/subscriptions",
      "apiBaseUrl": "https://api.lemonsqueezy.com/v1/",
      "method": "GET",
      "sampleResponse": {
        "data": [
          {
            "id": "3001",
            "attributes": {
              "status": "active",
              "billing_interval": "monthly"
            }
          }
        ]
      },
      "inputSchema": {
        "type": "object",
        "description": "Optional filters to search subscriptions.",
        "properties": {
          "store_id": {
            "type": "string",
            "description": "ID of the store associated with the subscription."
          },
          "customer_id": {
            "type": "string",
            "description": "ID of the customer who owns the subscription."
          },
          "order_id": {
            "type": "string",
            "description": "ID of the order that created the subscription."
          },
          "product_id": {
            "type": "string",
            "description": "ID of the product for the subscription."
          },
          "variant_id": {
            "type": "string",
            "description": "ID of the product variant for the subscription."
          },
          "status": {
            "type": "string",
            "description": "Status of the subscription (e.g., active, cancelled)."
          }
        }
      },
      "outputType": {
        "outputType": "array",
        "arrayPropertyValue": "data"
      }
    },
    {
      "title": "Find Product Details",
      "description": "Retrieves detailed information about a specific product by its ID.",
      "type": "action",
      "documentation": "https://docs.lemonsqueezy.com/api/products#get-product",
      "endpointUrl": "/products/{id}",
      "apiBaseUrl": "https://api.lemonsqueezy.com/v1/",
      "method": "GET",
      "sampleResponse": {
        "data": {
          "id": "101",
          "attributes": {
            "name": "Digital Course",
            "description": "Complete course details and metadata."
          }
        }
      },
      "inputSchema": {
        "type": "object",
        "description": "Input requires the product ID.",
        "properties": {
          "id": {
            "type": "string",
            "description": "Product ID."
          }
        }
      },
      "outputType": {
        "outputType": "object"
      }
    },
    {
      "title": "Find Order Details",
      "description": "Retrieves detailed information about a specific order by its ID.",
      "type": "action",
      "documentation": "https://docs.lemonsqueezy.com/api/orders#get-order",
      "endpointUrl": "/orders/{id}",
      "apiBaseUrl": "https://api.lemonsqueezy.com/v1/",
      "method": "GET",
      "sampleResponse": {
        "data": {
          "id": "9001",
          "attributes": {
            "status": "completed",
            "total": "49.99"
          }
        }
      },
      "inputSchema": {
        "type": "object",
        "description": "Input requires the order ID.",
        "properties": {
          "id": {
            "type": "string",
            "description": "Order ID."
          }
        }
      },
      "outputType": {
        "outputType": "object"
      }
    },
    {
      "title": "Find Subscription Details",
      "description": "Retrieves detailed information about a specific subscription by its ID.",
      "type": "action",
      "documentation": "https://docs.lemonsqueezy.com/api/subscriptions#get-subscription",
      "endpointUrl": "/subscriptions/{id}",
      "apiBaseUrl": "https://api.lemonsqueezy.com/v1/",
      "method": "GET",
      "sampleResponse": {
        "data": {
          "id": "3001",
          "attributes": {
            "status": "active",
            "next_billing_date": "2023-11-01"
          }
        }
      },
      "inputSchema": {
        "type": "object",
        "description": "Input requires the subscription ID.",
        "properties": {
          "id": {
            "type": "string",
            "description": "Subscription ID."
          }
        }
      },
      "outputType": {
        "outputType": "object"
      }
    }
  ],
  "authentication": {
    "type": "apiKey",
    "authUrl": "",
    "tokenUrl": "",
    "profileInfoUrl": ""
  },
  "serviceJson": {
    "name": "appmixer.lemonsqueezy",
    "label": "Lemon Squeezy",
    "category": "applications",
    "description": "Integration with Lemon Squeezy for managing digital product sales, subscriptions, orders, and customer data.",
    "version": "1.0.0",
    "icon": "https://upload.wikimedia.org/wikipedia/commons/c/c9/Lemon_icon.svg"
  }
}
